S = "Hakeem Force Academy"
QS = [
(S, "What is the closest meaning (synonym) of the word insurgence?", ["Rebellion", "Agreement", "Surrender", "Celebration"], 0, "Insurgence means an uprising or revolt against an authority. Rebellion has the same meaning.", "An insurgent is a person who rises in revolt against a government.", [3400]),
(S, "What is the closest meaning (synonym) of the word languish?", ["Flourish", "Weaken", "Hurry", "Argue"], 1, "To languish means to lose strength or to stay in a poor state for a long time. Weaken is the nearest meaning.", "The opposite of languish is flourish or thrive.", [1163]),
(S, "What is the closest meaning (synonym) of the word momentary?", ["Eternal", "Brief", "Heavy", "Important"], 1, "Momentary means lasting only for a moment. Brief means lasting a short time.", "The opposite of momentary is lasting or permanent.", [3401]),
(S, "What is the closest meaning (synonym) of the word normal?", ["Strange", "Rare", "Ordinary", "Violent"], 2, "Normal means usual and as expected. Ordinary has the same meaning.", "The opposite of normal is abnormal or unusual.", [3402]),
(S, "What is the closest meaning (synonym) of the word pragmatic?", ["Dreamy", "Practical", "Careless", "Emotional"], 1, "A pragmatic person deals with things in a sensible and realistic way. Practical has the same meaning.", "The opposite of pragmatic is idealistic or impractical.", [3406]),
(S, "What is the closest meaning (synonym) of the word spurn?", ["Accept", "Praise", "Follow", "Reject"], 3, "To spurn means to refuse something with scorn. Reject is the nearest meaning.", "Spurn can also be used as a noun in old English for a kick, but the common meaning is to refuse.", [212]),
(S, "What is the closest meaning (synonym) of the word tamper?", ["Repair", "Interfere", "Protect", "Measure"], 1, "To tamper means to interfere with something in order to damage or change it without permission. Interfere is the nearest meaning.", "Tampering with evidence is a crime in most countries.", [3408]),
(S, "Where were all the Round Table Conferences (1930 to 1932) held?", ["Delhi", "Bombay", "Karachi", "London"], 3, "The three Round Table Conferences were held in London to discuss constitutional reforms for India. They took place in 1930, 1931 and 1932.", "The Muslim League was represented by Quaid-e-Azam Muhammad Ali Jinnah and Allama Iqbal attended the second session.", [51]),
(S, "In which district and province is the Tanda Dam located?", ["Kohat, Khyber Pakhtunkhwa", "Attock, Punjab", "Quetta, Balochistan", "Hyderabad, Sindh"], 0, "Tanda Dam is a small dam built near Kohat in Khyber Pakhtunkhwa. It supplies drinking and irrigation water.", "Kohat is also known for its tunnel, the Kohat Pass and its cantonment.", [3823, 2210]),
(S, "In which district of Punjab is Tandlianwala located?", ["Sialkot", "Multan", "Faisalabad", "Sargodha"], 2, "Tandlianwala is a city and tehsil in Faisalabad district of Punjab.", "Faisalabad was earlier named Lyallpur.", [3763, 3762]),
(S, "Tarbela Dam construction began in 1968 during whose rule?", ["Ayub Khan", "Liaquat Ali Khan", "Yahya Khan", "Zia-ul-Haq"], 0, "Work on Tarbela Dam started in 1968 when Field Marshal Ayub Khan was President. It followed the Indus Waters Treaty of 1960.", "The dam was completed in 1976 during the time of Zulfikar Ali Bhutto.", [2601, 2602]),
(S, "Which two teams play the Ashes, regarded as the greatest rivalry in Test cricket?", ["England and Australia", "Pakistan and India", "West Indies and England", "Australia and South Africa"], 0, "The Ashes is the oldest and most famous Test series, played between England and Australia. It began in 1882.", "The winner holds a small urn containing the symbolic ashes.", [1613]),
(S, "When did the Gandhi-Jinnah talks take place in Bombay?", ["September 1944", "March 1940", "June 1946", "August 1947"], 0, "Gandhi met Quaid-e-Azam Jinnah at his house in Bombay from 9 to 27 September 1944. The talks failed because they did not agree on the Pakistan demand.", "Gandhi's proposal was based on the Rajagopalachari formula.", [3510, 3599, 3685]),
(S, "Which tense is used in the sentence: They are watching TV?", ["Present continuous", "Present simple", "Past continuous", "Future simple"], 0, "The verb group are watching uses is/am/are plus verb-ing, which shows an action happening now. This is the present continuous tense.", "The past continuous form would be: They were watching TV.", [4323]),
(S, "What is the tenure (term) of the National Assembly of Pakistan, unless it is dissolved earlier?", ["Three years", "Four years", "Six years", "Five years"], 3, "Under the 1973 Constitution the National Assembly lasts five years from its first meeting. After that it stops working automatically.", "The Senate is a permanent house and is never dissolved.", [681, 682]),
(S, "What is the tenure of a member of the Senate of Pakistan?", ["Five years", "Six years", "Four years", "Three years"], 1, "A Senator is elected for six years. Half of the members retire every three years.", "The Senate is a permanent house and cannot be dissolved.", [215, 683]),
(S, "If 1 = 7 and 3 = 9, then 13 = ?", ["19", "15", "21", "17"], 0, "Each number is 6 more than the given number: 1 + 6 = 7 and 3 + 6 = 9. So 13 + 6 = 19.", "In such code questions first find the rule that fits all the given examples.", [1921]),
(S, "What is one third of 20% of 60?", ["3", "6", "4", "12"], 2, "20% of 60 = 12. One third of 12 = 4.", "To find a percentage, multiply by the percent and divide by 100.", [2926]),
(S, "What is one third of 30% of 120?", ["12", "36", "10", "9"], 0, "30% of 120 = 36. One third of 36 = 12.", "30% of a number equals three tenths of it.", [2928]),
(S, "What is one third of 95?", ["30", "31 and 2/3", "32", "28 and 1/3"], 1, "95 divided by 3 = 31 with remainder 2, so the answer is 31 and 2/3 (31.67).", "A number is divisible by 3 if the sum of its digits is divisible by 3; 9 + 5 = 14 is not.", [2927]),
(S, "Ali's age is 5 years and his sister is three times his age. What will be his sister's age when Ali is 20?", ["60", "35", "45", "30"], 3, "Sister's age now = 3 x 5 = 15, so she is 10 years older than Ali. When Ali is 20, she will be 20 + 10 = 30.", "The age difference between two persons always stays the same.", [1976]),
(S, "Hania is 4 years old and her sister is three times her age. What will her sister's age be when Hania is 10?", ["30", "18", "22", "12"], 1, "Sister's age now = 3 x 4 = 12, so she is 8 years older. When Hania is 10, the sister will be 10 + 8 = 18.", "The age difference between two persons always stays the same.", [1982]),
(S, "Choose the correct word: We went to the picnic ____ car.", ["through", "of", "on", "by"], 3, "We use by with means of transport, as in by car, by bus, by train.", "With some transport we use on, as in on foot or on a bus.", [2732]),
(S, "In which game is a free throw used?", ["Hockey", "Basketball", "Football", "Cricket"], 1, "A free throw is an unopposed shot at the basket given to a player after a foul in basketball. It is worth one point.", "A basket scored from inside the three-point line in open play is worth two points.", [405]),
(S, "Who is known as the Tiger of Mysore?", ["Hyder Ali", "Bahadur Shah Zafar", "Tipu Sultan", "Siraj-ud-Daulah"], 2, "Tipu Sultan, the ruler of Mysore, was called the Tiger of Mysore because of his bravery. He fought the British in the Mysore Wars.", "Tipu Sultan was killed in 1799 when the British defeated him at Seringapatam.", [4468, 1338, 193]),
]
